WITH x AS (SELECT o.customer_id,o.order_id,o.ordered_at,SUM(i.quantity*i.unit_price_cents) AS cents FROM orders o JOIN order_items i ON i.order_id=o.order_id WHERE o.status='paid' GROUP BY o.customer_id,o.order_id,o.ordered_at) SELECT customer_id,order_id,SUM(cents) OVER(PARTITION BY customer_id ORDER BY ordered_at,order_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cents FROM x ORDER BY customer_id,ordered_at,order_id;
